 static int Main(string[] a){try{string w=a[0],feed=a[2];var r=ReleaseInfo.Read(File.ReadAllText(feed),"v8h-hd-v54-ui-v4");var c=new Settings{SourceIso=a[1],DataRoot=Path.Combine(w,"iso-mode-test","Data")};if(Directory.Exists(c.DataRoot))throw new Exception("fresh fixture required");var e=new Engine(c,Path.Combine(w,"iso-mode-test","settings.json"),Path.Combine(w,"tools"));e.Progress=(s,p)=>Console.WriteLine(s);string cache=Path.Combine(c.DataRoot,"downloads",r.Tag);Directory.CreateDirectory(cache);File.Copy(Path.Combine(Path.GetDirectoryName(feed),r.Base.Name),Path.Combine(cache,r.Base.Name));e.Install(r,true,false,false,false);Engine.Verify(c.GameIso,r.TargetBytes,r.TargetHash);if(c.GameData!=""||c.UseExternalData||!Engine.HasGame(c))throw new Exception("ISO mode state incorrect");Json.Write(Path.Combine(w,"iso-mode-check.json"),new{status="PASS",target_sha256=r.TargetHash,legacy_install_preserved=true,external_profile_touched=false});return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
